<?php
require_once __DIR__ . '/config.php';send_cors_headers();$data=json_input();$id=(int)value($data,'id');if(!$id){http_response_code(422);echo json_encode(['success'=>false]);exit;}$conn=db();$q=$conn->prepare('SELECT name,company FROM departments WHERE id=?');$q->bind_param('i',$id);$q->execute();$d=$q->get_result()->fetch_assoc();$q->close();if(!$d){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Department not found.']);exit;}$count=$conn->prepare('SELECT COUNT(*) total FROM employees WHERE LOWER(department)=LOWER(?) AND LOWER(company)=LOWER(?)');$count->bind_param('ss',$d['name'],$d['company']);$count->execute();$used=(int)$count->get_result()->fetch_assoc()['total'];$count->close();if($used>0){http_response_code(409);echo json_encode(['success'=>false,'message'=>'Cannot delete a department with assigned employees.']);$conn->close();exit;}$stmt=$conn->prepare('DELETE FROM departments WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();log_activity($conn,'HR','Department deleted',$d['name'].' · '.$d['company']);echo json_encode(['success'=>true]);$stmt->close();$conn->close();
